// checks that a sliding-window KV cache places every position p of a sequence at cell p % C, C the ring's cell count,
// through in-order fills, truncations (also ones whose freed positions wrap the ring), speculative rollbacks, ubatch
// splits and state save/load, and that the full-attention cache next to it places its cells as it does without that
//
// runs on the CPU over the models in --models DIR (generated by test-llama-archs -o DIR), or over a single -m FILE

#include "llama.h"

// TODO: replace with #include "llama-ext.h" in the future
#include "../src/llama-kv-cache.h"
#include "../src/llama-kv-cache-dsa.h"
#include "../src/llama-kv-cache-dsa-iswa.h"
#include "../src/llama-kv-cache-dsv4.h"
#include "../src/llama-kv-cache-iswa.h"
#include "../src/llama-memory-hybrid-iswa.h"

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <functional>
#include <random>
#include <string>
#include <vector>

static const char * DISABLE_ENV = "LLAMA_KV_SWA_POS_PLACEMENT_DISABLE";

// the sliding-window cache of a memory and the full-attention cache beside it, null when the memory has none
struct caches {
    const llama_kv_cache * swa  = nullptr;
    const llama_kv_cache * full = nullptr;
};

static caches get_caches(llama_context * ctx) {
    llama_memory_i * mem = llama_get_memory(ctx);
    if (auto * m = dynamic_cast<llama_kv_cache_iswa *>(mem)) {
        return { m->get_swa(), m->get_base() };
    }
    if (auto * m = dynamic_cast<llama_memory_hybrid_iswa *>(mem)) {
        return { m->get_mem_attn()->get_swa(), m->get_mem_attn()->get_base() };
    }
    if (auto * m = dynamic_cast<llama_kv_cache_dsa_iswa *>(mem)) {
        return { m->get_swa(), m->get_dsa()->get_mla() };
    }
    if (auto * m = dynamic_cast<llama_kv_cache_dsv4 *>(mem)) {
        return { m->get_raw()->get_swa(), m->get_raw()->get_base() };
    }
    return {};
}

struct ctx_config {
    uint32_t n_seq_max   = 1;
    bool     unified     = false;
    bool     placement   = true; // false sets the disable variable while the context is built
    uint32_t n_rs_seq    = 0;
};

static llama_context * make_ctx(llama_model * model, const ctx_config & cfg) {
    llama_context_params cparams = llama_context_default_params();
    cparams.n_ctx           = 2048 * cfg.n_seq_max;
    cparams.n_batch         = 512;
    cparams.n_ubatch        = 32;
    cparams.n_seq_max       = cfg.n_seq_max;
    cparams.n_rs_seq        = cfg.n_rs_seq;
    cparams.kv_unified      = cfg.unified;
    cparams.swa_full        = false;
    cparams.offload_kqv     = false;
    cparams.op_offload      = false;
    cparams.n_threads       = 4;
    cparams.n_threads_batch = 4;

    if (!cfg.placement) {
        setenv(DISABLE_ENV, "1", 1);
    }
    llama_context * ctx = llama_init_from_model(model, cparams);
    unsetenv(DISABLE_ENV);

    return ctx;
}

struct runner {
    llama_context * ctx;
    int n_vocab;
    std::mt19937 rng { 42 };

    llama_token tok() {
        return (llama_token) (rng() % (uint32_t) n_vocab);
    }

    // decode positions [p0, p1) of seq in one batch; the batch splits into ubatches of n_ubatch
    bool decode(llama_seq_id seq, llama_pos p0, llama_pos p1) {
        llama_batch batch = llama_batch_init(p1 - p0, 0, 1);
        for (llama_pos p = p0; p < p1; ++p) {
            const int i = batch.n_tokens++;
            batch.token   [i]    = tok();
            batch.pos     [i]    = p;
            batch.n_seq_id[i]    = 1;
            batch.seq_id  [i][0] = seq;
            batch.logits  [i]    = p + 1 == p1;
        }
        const int ret = llama_decode(ctx, batch);
        llama_batch_free(batch);
        return ret == 0;
    }

    // decode [p0, p1) of seq in batches of n tokens
    bool decode_in(llama_seq_id seq, llama_pos p0, llama_pos p1, llama_pos n) {
        for (llama_pos p = p0; p < p1; p += n) {
            if (!decode(seq, p, std::min(p + n, p1))) {
                return false;
            }
        }
        return true;
    }

    bool rm(llama_seq_id seq, llama_pos p0) {
        return llama_memory_seq_rm(llama_get_memory(ctx), seq, p0, -1);
    }
};

// the number of cells of seq's stream in the ring that hold a position off its cell, plus the positions of
// [pos_min, pos_max] of seq that are not at their cell
static int count_off(llama_context * ctx, llama_seq_id seq) {
    const llama_kv_cells & cells = get_caches(ctx).swa->get_cells(seq);
    const llama_pos size = cells.size();

    int n_off = 0;
    for (uint32_t i = 0; i < cells.size(); ++i) {
        if (!cells.is_empty(i) && cells.pos_get(i) % size != (llama_pos) i) {
            ++n_off;
        }
    }

    const llama_pos p0 = cells.seq_pos_min(seq);
    const llama_pos p1 = cells.seq_pos_max(seq);
    for (llama_pos p = std::max<llama_pos>(p0, 0); p0 >= 0 && p <= p1; ++p) {
        const uint32_t idx = p % size;
        if (cells.is_empty(idx) || cells.pos_get(idx) != p || !cells.seq_has(idx, seq)) {
            ++n_off;
        }
    }

    return n_off;
}

static int g_n_fail = 0;

static void expect(bool ok, const std::string & model, const char * what) {
    if (!ok) {
        fprintf(stderr, "FAIL %s: %s\n", model.c_str(), what);
        ++g_n_fail;
    }
}

// the mapping holds for seq and the query says so
static bool modular(llama_context * ctx, llama_seq_id seq) {
    const llama_memory_swa_placement pl = llama_memory_seq_swa_placement(llama_get_memory(ctx), seq);
    return pl.position_modular && pl.in_force && count_off(ctx, seq) == 0;
}

// fill the ring twice and a bit, then remove the tail so that the freed positions wrap the ring
// returns the first position to decode next, or -1 on a failure
static llama_pos wrap_truncate(runner & r, llama_seq_id seq, uint32_t C) {
    const llama_pos n_fill = 2*C + 40;
    if (!r.decode_in(seq, 0, n_fill, 100)) {
        return -1;
    }
    // [2C - 30, 2C + 40) sits in cells [C - 30, C) and [0, 40)
    const llama_pos q = 2*C - 30;
    if (!r.rm(seq, q)) {
        return -1;
    }
    return q;
}

// speculative-style rollback: decode a draft of 1..8 tokens, keep a prefix, remove the rest, until the ring has
// wrapped three times. keep_one keeps at least one token of every draft, as a recurrent rollback needs
static bool spec_loop(runner & r, llama_context * ctx, uint32_t C, bool keep_one) {
    llama_memory_clear(llama_get_memory(ctx), true);
    bool ok = r.decode(0, 0, 20);
    llama_pos p = 20;
    while (ok && p < (llama_pos) (3*C)) {
        const llama_pos d = 1 + r.rng() % 8;
        const llama_pos a = keep_one ? 1 + r.rng() % d : r.rng() % (d + 1);
        ok = r.decode(0, p, p + d) && modular(ctx, 0);
        ok = ok && r.rm(0, p + a) && modular(ctx, 0);
        p += a;
    }
    return ok;
}

struct coverage {
    int n_models    = 0;
    int n_ring      = 0;
    int n_whole     = 0; // rings that hold the whole context, so they never wrap
    int n_spec_only = 0; // memories that remove only a recurrent rollback's worth of tokens
    int n_trunc     = 0;
    int n_negative  = 0;
};

static void test_model(const std::string & path, coverage & cov) {
    llama_model_params mparams = llama_model_default_params();
    static ggml_backend_dev_t no_devices[] = { nullptr };
    mparams.devices      = no_devices;
    mparams.n_gpu_layers = 0;
    mparams.progress_callback = [](float, void *) { return true; };

    llama_model * model = llama_model_load_from_file(path.c_str(), mparams);
    if (!model) {
        fprintf(stderr, "FAIL %s: cannot load\n", path.c_str());
        ++g_n_fail;
        return;
    }

    const std::string name = std::filesystem::path(path).filename().string();
    const int n_vocab = llama_vocab_n_tokens(llama_model_get_vocab(model));

    cov.n_models++;

    llama_context * ctx = make_ctx(model, {});
    if (!ctx) {
        printf("%-40s no context with these parameters, skipped\n", name.c_str());
        llama_model_free(model);
        return;
    }

    const llama_memory_swa_placement pl = llama_memory_seq_swa_placement(llama_get_memory(ctx), 0);
    if (pl.n_cells == 0 || !get_caches(ctx).swa) {
        llama_free(ctx);
        llama_model_free(model);
        return;
    }

    const uint32_t C = pl.n_cells;
    printf("%-40s ring of %u cells, n_swa %u, position_modular %d\n", name.c_str(), C, pl.n_swa, pl.position_modular);
    expect(pl.position_modular && pl.in_force, name, "a single-sequence ring places by position");
    expect(llama_memory_seq_swa_placement(nullptr, 0).n_cells == 0, name, "a null memory reports no ring");
    cov.n_ring++;

    runner r { ctx, n_vocab };

    // a window wider than the context leaves the ring as large as the context: positions never reach C
    if (pl.n_swa + 32 > C + 1) {
        llama_pos p = 0;
        bool ok = true;
        for (llama_pos n : { 1, 7, 100, 1, 250 }) {
            ok = ok && r.decode(0, p, p + n) && modular(ctx, 0);
            p += n;
        }
        expect(ok, name, "in-order fill of a ring that holds the whole context keeps p at p % C");
        printf("%-40s ring holds the whole context: wrap scenarios not run\n", name.c_str());
        cov.n_whole++;
        llama_free(ctx);
        llama_model_free(model);
        return;
    }

    // in-order fill: single tokens, short batches, and batches that split into several ubatches
    {
        llama_pos p = 0;
        bool ok = true;
        for (llama_pos n : { 1, 1, 7, 32, 100, 1, 3, 250, 64, 1 }) {
            ok = ok && r.decode(0, p, p + n);
            p += n;
            ok = ok && modular(ctx, 0);
        }
        expect(ok && p > (llama_pos) C, name, "in-order fill keeps p at p % C");
    }

    // a truncation that does not wrap, then one whose freed positions wrap the ring
    llama_memory_clear(llama_get_memory(ctx), true);
    const bool can_truncate = r.decode(0, 0, 10) && r.rm(0, 5);
    llama_memory_clear(llama_get_memory(ctx), true);

    if (!can_truncate) {
        // a recurrent memory removes as many tokens as it keeps rollback snapshots
        llama_context * ctx_rs = make_ctx(model, { 1, false, true, 8 });
        runner r_rs { ctx_rs, n_vocab };
        expect(ctx_rs && spec_loop(r_rs, ctx_rs, C, true), name, "speculative rollback loops keep p at p % C (n_rs_seq 8)");
        printf("%-40s removes only rollbacks of up to 8 tokens: only the speculative scenario run\n", name.c_str());
        cov.n_spec_only++;
        llama_free(ctx_rs);
    } else {
        cov.n_trunc++;

        bool ok = r.decode_in(0, 0, 2*C + 40, 100);
        ok = ok && r.rm(0, 2*C + 10) && modular(ctx, 0);
        ok = ok && r.decode(0, 2*C + 10, 2*C + 11) && modular(ctx, 0);
        ok = ok && r.decode(0, 2*C + 11, 2*C + 80) && modular(ctx, 0);
        expect(ok, name, "a truncation inside the ring, then continue");

        llama_memory_clear(llama_get_memory(ctx), true);
        const llama_pos q = wrap_truncate(r, 0, C);
        ok = q >= 0 && modular(ctx, 0);
        for (llama_pos p = q; ok && p < q + 10; ++p) {
            ok = r.decode(0, p, p + 1) && modular(ctx, 0);
        }
        ok = ok && r.decode(0, q + 10, q + 80) && modular(ctx, 0);
        expect(ok, name, "a truncation whose freed positions wrap the ring, then continue");

        expect(spec_loop(r, ctx, C, false), name, "speculative rollback loops keep p at p % C");

        // state save/load of the sequence, after a wrapped truncation
        llama_memory_clear(llama_get_memory(ctx), true);
        const llama_pos qs = wrap_truncate(r, 0, C);
        ok = qs >= 0 && r.decode(0, qs, qs + 5);
        std::vector<uint8_t> seq_state(llama_state_seq_get_size(ctx, 0));
        ok = ok && llama_state_seq_get_data(ctx, seq_state.data(), seq_state.size(), 0) == seq_state.size();
        const std::vector<llama_pos> cells_before = [&] {
            std::vector<llama_pos> v;
            const auto & cells = get_caches(ctx).swa->get_cells(0);
            for (uint32_t i = 0; i < cells.size(); ++i) {
                v.push_back(cells.is_empty(i) ? -1 : cells.pos_get(i));
            }
            return v;
        }();
        llama_memory_clear(llama_get_memory(ctx), true);
        ok = ok && llama_state_seq_set_data(ctx, seq_state.data(), seq_state.size(), 0) == seq_state.size();
        ok = ok && modular(ctx, 0);
        {
            const auto & cells = get_caches(ctx).swa->get_cells(0);
            for (uint32_t i = 0; ok && i < cells.size(); ++i) {
                ok = (cells.is_empty(i) ? -1 : cells.pos_get(i)) == cells_before[i];
            }
        }
        ok = ok && r.decode(0, qs + 5, qs + 60) && modular(ctx, 0);
        expect(ok, name, "a sequence state load keeps p at p % C");

        // whole-context state save/load
        std::vector<uint8_t> state(llama_state_get_size(ctx));
        ok = llama_state_get_data(ctx, state.data(), state.size()) == state.size();
        llama_memory_clear(llama_get_memory(ctx), true);
        ok = ok && llama_state_set_data(ctx, state.data(), state.size()) == state.size();
        ok = ok && modular(ctx, 0) && r.decode(0, qs + 60, qs + 100) && modular(ctx, 0);
        expect(ok, name, "a context state load keeps p at p % C");

        // cell metadata snapshot/restore around a rollback
        llama_memory_cells_t snap = llama_memory_cells_snapshot(llama_get_memory(ctx), 0);
        ok = snap != nullptr && r.decode(0, qs + 100, qs + 108) && r.rm(0, qs + 100);
        llama_memory_cells_restore(llama_get_memory(ctx), 0, snap);
        llama_memory_cells_free(snap);
        ok = ok && modular(ctx, 0) && r.decode(0, qs + 100, qs + 104) && modular(ctx, 0);
        expect(ok, name, "a cell snapshot restore keeps p at p % C");

        // a ubatch that needs one cell twice is refused, and the cells stay as they were
        {
            const llama_pos pn = llama_memory_seq_pos_max(llama_get_memory(ctx), 0) + 1;
            llama_batch batch = llama_batch_init(2, 0, 1);
            for (int i = 0; i < 2; ++i) {
                batch.token[i] = r.tok(); batch.pos[i] = pn; batch.n_seq_id[i] = 1; batch.seq_id[i][0] = 0; batch.logits[i] = i == 1;
            }
            batch.n_tokens = 2;
            const int ret = llama_decode(ctx, batch);
            llama_batch_free(batch);
            expect(ret == 1 && modular(ctx, 0) && llama_memory_seq_pos_max(llama_get_memory(ctx), 0) == pn - 1, name,
                    "two tokens for one cell fail the slot search instead of taking another cell");
        }

        // the full-attention cache places its cells the same with and without the policy, and reports no ring
        {
            llama_context * ctx_off = make_ctx(model, { 1, false, false });
            runner r_off { ctx_off, n_vocab };

            const llama_memory_swa_placement pl_off = llama_memory_seq_swa_placement(llama_get_memory(ctx_off), 0);
            expect(pl_off.n_cells == C && !pl_off.position_modular && !pl_off.in_force, name, "the disabled ring reports no position placement");

            llama_memory_clear(llama_get_memory(ctx), true);
            r.rng.seed(7);
            r_off.rng.seed(7);
            const llama_pos q_on  = wrap_truncate(r,     0, C);
            const llama_pos q_off = wrap_truncate(r_off, 0, C);
            ok = q_on >= 0 && q_off >= 0 && r.decode(0, q_on, q_on + 20) && r_off.decode(0, q_off, q_off + 20);

            // negative control: without the policy the next tokens take the lowest freed cells, off p % C
            const int n_off = count_off(ctx_off, 0);
            printf("%-40s negative control: %d cells off p %% C without the policy, %d with it\n", name.c_str(), n_off, count_off(ctx, 0));
            expect(ok && n_off > 0, name, "negative control: the wrapped truncation lands off p % C without the policy");
            cov.n_negative += ok && n_off > 0;

            // a sequence state saved without the policy restores onto the placement when no two of its positions
            // share a cell, and off it, searching for free cells, when two do
            {
                const auto & cells_off = get_caches(ctx_off).swa->get_cells(0);
                std::vector<bool> seen(C, false);
                bool distinct = true;
                for (uint32_t i = 0; i < cells_off.size(); ++i) {
                    if (!cells_off.is_empty(i)) {
                        const uint32_t idx = cells_off.pos_get(i) % C;
                        distinct = distinct && !seen[idx];
                        seen[idx] = true;
                    }
                }

                std::vector<uint8_t> st(llama_state_seq_get_size(ctx_off, 0));
                bool ok2 = llama_state_seq_get_data(ctx_off, st.data(), st.size(), 0) == st.size();
                llama_memory_clear(llama_get_memory(ctx), true);
                ok2 = ok2 && llama_state_seq_set_data(ctx, st.data(), st.size(), 0) == st.size();
                const bool in_force = llama_memory_seq_swa_placement(llama_get_memory(ctx), 0).in_force;
                ok2 = ok2 && in_force == distinct && (count_off(ctx, 0) == 0) == distinct;
                const llama_pos pn = llama_memory_seq_pos_max(llama_get_memory(ctx), 0) + 1;
                ok2 = ok2 && r.decode(0, pn, pn + 40);
                printf("%-40s a state saved without the policy restores %s the placement\n", name.c_str(), distinct ? "onto" : "off");
                expect(ok2, name, "a sequence state saved without the policy restores and decodes on");

                // put ctx back where the comparison of the full-attention caches expects it
                llama_memory_clear(llama_get_memory(ctx), true);
                r.rng.seed(7);
                ok = ok && wrap_truncate(r, 0, C) == q_on && r.decode(0, q_on, q_on + 20);
            }

            const llama_kv_cache * full_on  = get_caches(ctx).full;
            const llama_kv_cache * full_off = get_caches(ctx_off).full;
            if (full_on && full_off) {
                const auto & a = full_on ->get_cells(0);
                const auto & b = full_off->get_cells(0);
                bool same = a.size() == b.size();
                for (uint32_t i = 0; same && i < a.size(); ++i) {
                    same = a.is_empty(i) == b.is_empty(i) && (a.is_empty(i) || a.pos_get(i) == b.pos_get(i));
                }
                expect(same, name, "the full-attention cache places its cells as without the policy");
                expect(full_on->swa_placement(0).n_cells == 0, name, "the full-attention cache reports no ring");
            }

            llama_free(ctx_off);
        }

        // moving positions takes the placement out of force until they are back on their cells
        {
            llama_memory_t mem = llama_get_memory(ctx);
            llama_memory_seq_add(mem, 0, -1, -1, 1);
            const llama_memory_swa_placement moved = llama_memory_seq_swa_placement(mem, 0);
            llama_memory_seq_add(mem, 0, -1, -1, -1);
            const llama_memory_swa_placement back = llama_memory_seq_swa_placement(mem, 0);
            expect(moved.position_modular && !moved.in_force && back.in_force, name, "a position shift is reported off the placement");
        }
    }

    llama_free(ctx);

    // a stream per sequence: each sequence keeps its own mapping, also when the two decode in one batch
    if (can_truncate) {
        llama_context * ctx2 = make_ctx(model, { 2, false, true });
        if (ctx2) {
            runner r2 { ctx2, n_vocab };
            bool ok = llama_memory_seq_swa_placement(llama_get_memory(ctx2), 1).position_modular;

            llama_batch batch = llama_batch_init(2*64, 0, 1);
            for (llama_pos p0 = 0; ok && p0 < (llama_pos) (2*C + 40); p0 += 64) {
                batch.n_tokens = 0;
                for (llama_seq_id s = 0; s < 2; ++s) {
                    for (llama_pos p = p0; p < p0 + 64; ++p) {
                        const int i = batch.n_tokens++;
                        batch.token[i] = r2.tok(); batch.pos[i] = p; batch.n_seq_id[i] = 1; batch.seq_id[i][0] = s; batch.logits[i] = false;
                    }
                }
                batch.logits[batch.n_tokens - 1] = true;
                ok = llama_decode(ctx2, batch) == 0;
            }
            llama_batch_free(batch);

            const llama_pos q = 2*C - 30;
            ok = ok && r2.rm(1, q) && r2.decode(1, q, q + 50);
            ok = ok && modular(ctx2, 0) && modular(ctx2, 1);
            expect(ok, name, "two sequences with a stream each keep p at p % C");
            llama_free(ctx2);
        }

        // a unified cache shared by two sequences cannot place by position
        llama_context * ctx3 = make_ctx(model, { 2, true, true });
        if (ctx3) {
            const llama_memory_swa_placement pu = llama_memory_seq_swa_placement(llama_get_memory(ctx3), 0);
            // a memory that keeps a stream per sequence whatever kv_unified is still places by position
            const bool per_seq = get_caches(ctx3).swa->get_n_stream() == 2;
            expect(pu.position_modular == per_seq, name, "a unified two-sequence ring does not place by position");
            llama_free(ctx3);
        }
    }

    llama_model_free(model);
}

int main(int argc, char ** argv) {
    std::string models_dir;
    std::string model_path;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--models") == 0 && i + 1 < argc) {
            models_dir = argv[++i];
        } else if (strcmp(argv[i], "-m") == 0 && i + 1 < argc) {
            model_path = argv[++i];
        } else {
            fprintf(stderr, "usage: %s --models DIR | -m FILE\n", argv[0]);
            return 1;
        }
    }

    std::vector<std::string> models;
    if (!model_path.empty()) {
        models.push_back(model_path);
    } else if (!models_dir.empty() && std::filesystem::is_directory(models_dir)) {
        for (const auto & entry : std::filesystem::directory_iterator(models_dir)) {
            if (entry.is_regular_file() && entry.path().extension() == ".gguf") {
                models.push_back(entry.path().string());
            }
        }
        std::sort(models.begin(), models.end());
    }

    if (models.empty()) {
        fprintf(stderr, "%s: no models\n", argv[0]);
        return 1;
    }

    llama_backend_init();
    llama_log_set([](ggml_log_level level, const char * text, void *) {
        if (level >= GGML_LOG_LEVEL_ERROR) {
            fputs(text, stderr);
        }
    }, nullptr);

    coverage cov;
    for (const auto & m : models) {
        test_model(m, cov);
    }

    llama_backend_free();

    // a run that found no ring, or never ran a truncation or the negative control, asserted nothing about them
    printf("coverage: %d models, %d with a ring (%d hold the whole context, %d remove only rollbacks), "
            "%d ran the truncation scenarios, %d negative controls bit\n",
            cov.n_models, cov.n_ring, cov.n_whole, cov.n_spec_only, cov.n_trunc, cov.n_negative);

    if (cov.n_ring == 0 || cov.n_trunc == 0 || cov.n_negative != cov.n_trunc) {
        fprintf(stderr, "FAIL: the run did not cover the placement\n");
        ++g_n_fail;
    }

    printf("%s: %d failures\n", argv[0], g_n_fail);

    return g_n_fail == 0 ? 0 : 1;
}
